insert into public.questions (id, subtopic_id, stable_code, prompt, explanation, status, sort_order)
values
  ('71537cb6-1004-424f-ad5b-8a240ca88a73', '534e4d64-402f-3719-316a-6da910b558fa', '1-1-01', '下列何者為自然色彩？', '本單元探討色彩的來源，核心觀念在於光色原理與可見光譜。英國科學家牛頓於1666年利用三棱鏡將太陽光（白光／複色光）分解為紅、橙、黃、綠、藍、靛、紫等七色光譜，揭開了光與色彩的關係。人類眼睛能感知的範圍稱為可見光譜（波長約380nm至780nm），而無法再經由三棱鏡分解的單一色光則稱為單色光。', 'published', 1),
  ('b3901734-11e9-850a-6d7d-a29a7895c590', '171b4ec0-88cf-0b02-ff94-fd08893e802d', '1-2-01', '下列生物何者不具有色覺？', '本單元探討色彩與生活，核心觀念在於生活中色彩的感知與應用。色彩廣泛存在於我們的日常環境中，不僅能引發心理上的冷暖、輕重、前進與後退等感覺，更在品牌設計、視覺傳達與生活美感教育中扮演重要角色。透過對生活中色彩的察覺與分析，能提升對美感的認知與色彩配置的能力。', 'published', 1),
  ('6514aeee-ce08-e04b-0c24-9e4ac863835a', '5e9f788b-0071-ca7c-7c25-8d50ab0822f2', '1-3-01', '在法國拉斯考洞穴壁面上，一萬多年前的人類以色彩描繪馬、牛、豬、鹿及狩獵圖畫，其中所用的色彩何者為非？', '本單元探討色彩的發展歷程，核心觀念在於人類對色彩認知與應用的歷史演變。從遠古時期原始人利用礦石、草木等自然素材塗繪洞窟壁畫，到古埃及時代將色料廣泛應用於墓穴畫。隨後歷經科學革命與近代發展，科學家與藝術家逐漸建立系統化的色彩理論與表色模型，為現代色彩學與數位色彩模式奠定了科學與藝術融合的基礎。', 'published', 1),
  ('1b5ccc19-88be-35c0-89e6-1a95633cbddf', '7ca4dc67-1bcd-7021-1aaa-97c7d9f599a7', '2-1-01', '西元1666年以三稜鏡分解太陽光分析出光譜的學者是？', '本單元探討色彩呈現，核心觀念在於色彩與光的關係。光是視覺現象的主要媒體，也是感知色彩的刺激物，沒有光就無法產生視覺。物體本身並沒有固定的色彩，其呈現的色彩會隨著光源條件而改變，當光線照射到物體上時，一部分光線被物體吸收，另一部分則被反射或透射，進而刺激人類眼睛並由大腦解讀，產生對色彩的感知。', 'published', 1),
  ('81c17787-3e3e-cb4c-1182-f9b935859d59', '6cd3f97b-df9a-a718-2e60-d46dad98856d', '2-2-01', '色光三原色是：', '本單元探討色光的原色與混色，核心觀念在於加法混色（加色混合、正混合）原理。色光三原色為紅（Red）、綠（Green）、藍（Blue），因其無法再被分解，也不能由其他色光混合而成。當不同比例的色光重疊混合時，其能量與明度會相加提升，兩兩等量混合可產生第二次色（紅+綠=黃、紅+藍=洋紅、藍+綠=青），而三原色等量混合則會組合成白光。', 'published', 1),
  ('02f6fc0c-e1ce-cf8a-0f70-8eacd9bffc02', 'a6644b36-ebdf-7f9e-5658-0cd923c817dc', '2-3-01', '色料三原色是指：', '本單元探討色料的原色與混合，核心觀念在於減法混色原理與色料三原色。色料三原色為青（Cyan）、洋紅（Magenta）、黃（Yellow），簡稱CMY，其特性為無法透過其他顏色混合而成。當不同的色料相混合時，由於色料會吸收光線，混合後的色彩明度與彩度會降低，且混合的顏色愈多，色彩愈顯暗濁，最終趨近於黑色，此現象稱為「減法混合」。在印刷或噴墨列印等實際應用中，通常會加入黑色（Black）以補足無法混出純黑的限制，形成CMYK四色印刷模式。', 'published', 1),
  ('ee088da1-b453-b431-2624-94c338d497d6', '155d9baa-d963-36d1-ec22-a6d96c34c5bb', '2-4-01', '某一畫面是由無數個色塊拼湊而成的混色效果，此種色彩混合類型稱為？', '本單元探討中間混合（又稱中性混合或平均混合），核心觀念在於其混色後的明度為原色彩的面積加權平均值。中間混合屬於生理性混色，主要分為「旋轉混色」（如旋轉的色標）與「並置混色」（如彩色印刷網點、織物經緯線、螢幕像素）。當不同色彩的細小點或線密集排列，或快速交替時，會超越人類眼睛的空間或時間解析度，因而在大腦中生理性地融合成新的中間色。', 'published', 1),
  ('79cb7f62-42c7-6e6f-bd92-a4a09cfc0630', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-01', '純色加入黑色所得的色彩稱為？', '本單元探討色彩表示，核心觀念在於色彩三要素與色名的表示。色彩三要素包含色相、明度和彩度（飽和度）。其中「明度」是指色彩的明暗程度，當純色混入白色時明度會提高，混入黑色時則會降低明度。而在色彩學的定義中，純色加入黑色所得的色彩稱為「暗色」。', 'published', 1),
  ('740fc7ce-b853-dace-d71f-cc7e4195da16', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-02', '明色和暗色因為不含灰色，所以又稱為？', '本單元探討色彩的分類與屬性。純色中只加入白色或黑色的色彩，由於不含有灰色，因此在色彩分類中被稱為「清色」；其中，純色加入白色所得到的明亮色彩稱為「明色」，純色加入黑色所得到的陰暗色彩則稱為「暗色」。', 'published', 2),
  ('2167dcf8-79a3-a784-b528-90711cb2a937', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-03', '在一個純色中，同時加入白色與黑色，就會成為：', '本單元探討色彩表示與色彩三要素，核心觀念在於純色、清色與濁色的定義。在色彩學中，不混入黑白色的色彩稱為純色；若純色中僅加入白色，則稱為明色（Tint）；若純色中僅加入黑色，則稱為暗色（Shade）。當一個純色中同時加入白色與黑色（即加入灰色），其彩度會降低，這種混合後的色彩便稱為濁色（Tone）或中間色。', 'published', 3),
  ('c55c13fe-0457-94c5-7055-41cb3074dc6a', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-04', '金色、銀色在色彩的分類中屬於：', '本單元探討色彩表示法。核心觀念在於特殊色的分類。金色與銀色具有獨特的金屬光澤，在色彩分類中，無法單純歸類為由彩料混合的有彩色或是不含彩度的無彩色（黑白灰），亦不屬於色彩的三原色或純色，而是屬於獨立色（又稱特殊色）。', 'published', 4),
  ('04990089-b8c6-dedd-d5ca-8a2864e879db', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-05', '下列色彩何者不屬於特殊色？', '本單元探討色彩表示，核心觀念在於色名的表示與分類。色彩可依據傳達方式分為「系統色名」與「固有色名（慣用色名）」，但在傳統或通用分類中，亦有將金色、銀色、螢光色或錫箔色等無法單純以色彩三屬性定義的顏色歸類為「特殊色」或「獨立色」。題目中的「七彩色」通常指光譜上的多色組合或彩虹色，不屬於單一特殊油墨或獨立特殊色的定義範圍。', 'published', 5),
  ('c2081b23-16be-289e-9c3a-ddafd0ccab97', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-06', '色彩的三屬性是：', '本單元探討色彩的表示，核心觀念在於色彩三要素（色彩三屬性）。凡是任何一個有彩色均具備「色相」、「明度」與「彩度」三個最基本條件。色相是指色彩的相貌與名稱；明度是指色彩的明暗程度；彩度則是區分色彩的鮮濁程度，亦即色彩的純度或鮮豔度。無彩色（如黑、灰、白）則僅有明度的差別，不具備色相與彩度。', 'published', 6),
  ('cf1bc8c5-3395-a8f8-ce77-fa4436eca6f9', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-07', '下列有關色相（Hue）的描述，何者不正確？', '本單元探討色彩表示，核心觀念在於色彩三要素與色名的表示。色相（Hue）指的是色彩的外相，亦即區別各種不同色彩的名稱，主要是由光的波長所決定，例如紅、黃、藍等不同的樣貌。至於以光線反射的強弱分出其間的感覺差異，所指的是色彩的「明度（Value）」，而非色相。', 'published', 7),
  ('a55323bc-c16f-9352-2658-252776208594', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-08', '關於「明度」的定義，下列何者錯誤？', '本單元探討色彩表示的要素，核心觀念在於明度的物理定義與主觀感受。明度（Value/Lightness）是指色彩的明暗或深淺程度，在物理學上主要取決於物體表面對光線的反射率（反射幅），反射率越高則明度越高。在色彩體系中，色光的波長是用來決定「色相」（Hue），而非決定明度，因此「色光的波長」不屬於明度的定義。', 'published', 8),
  ('b11aaec8-599b-c89b-183f-76d9d951ac21', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-09', '中國水墨畫「墨分五色」是利用色彩何種屬性的變化？', '本單元探討色彩三要素與色名的表示，核心觀念在於色彩的屬性與特質。中國水墨畫中的「墨分五色」是指利用水來調節墨色的濃淡乾濕，使其產生焦、濃、重、淡、清等不同層次，這種墨色深淺與明暗的變化，在色彩學中即屬於「明度」屬性的展現。', 'published', 9),
  ('ad0f0b65-8545-01d1-38a3-3e3f0c295726', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-10', '下列純色何者明度最高？', '本單元探討色彩表示中色彩三要素的特徵。明度是指色彩的明暗程度，亦即物體表面對光線反射率的多寡。在有彩色的純色當中，各個色相的明度皆不相同，其中黃色的反射率最高，屬於明度最高的有彩色純色；而藍色、紫色等色彩的明度則相對較低。', 'published', 10),
  ('1960b180-51cb-06c2-260a-ed863c657bfc', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-11', '依照曼塞爾（Munsell）表色系的明度階段，白、亮灰、淺灰的明度調子接近：', '本單元探討色彩表示，核心觀念在於色彩體系與數值符號。曼塞爾（Munsell）表色系將無彩色的明度（Value）由理想純黑（N0）至理想純白（N10）分為11個等距階段。在明度的調子分類中，白、亮灰、淺灰屬於高調子，其明度數值較大，接近理想純白的N10、N9、N8。', 'published', 11),
  ('2532dd66-45fe-8ec9-59ee-db66baf9db67', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-12', '曼塞爾（Munsell）表色系將明度由黑至白分為9個階段，所謂「低調子」指的是？', '曼塞爾表色系明度分為11個階段（N0至N10），若扣除理想純黑（N0）與理想純白（N10），實務上常分為9個階段（N1至N9）。其中N1、N2、N3屬於低明度階段，在色彩明度調子中被稱為「低調子」；中明度階段（N4、N5、N6）為「中調子」，高明度階段（N7、N8、N9）則為「高調子」。', 'published', 12),
  ('366f140d-ed2c-90f0-fce9-eb87571cc918', 'f929cde5-c294-46ce-5faf-c866b3cb9583', '3-1-13', '下列哪一色與白色混合後，明度階段變化最少的是：', '本單元探討色彩表示，核心觀念在於有彩色系中各色相與白色混合時的明度變化。在有彩色中，黃色的明度本身最高，與明度最高的白色最為接近，因此兩者混合後，明度的階段變化最少。', 'published', 13),
  ('9d185ad0-14fc-ef0a-f525-e6baec05d034', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-01', '最早提出色彩排列系統化理論的學者是：', '本單元探討色彩表示的歷史與發展，核心觀念在於色彩體系的系統化理論起源。最早將色彩排列系統化的學者是17世紀（1611年）瑞典的天文學家佛西士（Aron Sigfrid Forsius），他最早提出了色彩排列系統化的理論。而後續至19世紀初，德國畫家奧圖倫格（P. Otto Runge）則最先構想出球狀的三度空間色立體結構。', 'published', 1),
  ('27afe6b2-24d1-bf92-42bb-50eb58091f26', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-02', '某色在色相環上是舉足輕重的色彩，但在光譜上卻找不到，請問這個色彩是?', '本題探討色彩體系與數值符號。紅紫色（purple）在可見光譜中是找不到其單一波長的，它必須由光譜兩端的紅光與藍光混合而成。雖然它在光譜中不存在，但在色相環的排列上，紅紫色是連接紅色與藍紫色不可或缺的過渡橋樑，在色彩體系中具有舉足輕重的地位。', 'published', 2),
  ('8bfe9100-caac-4ff3-ab25-301ea27895e5', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-03', '色相環上通過圓之相對的兩個色彩互稱為：', '本單元探討色彩表示的體系，核心觀念在於色彩體系與數值符號。在色彩學中，色相環上通過圓之相對、即差距180度的兩個色彩，其色彩差異最大，在視覺上具有強烈的對比性，這兩個互為對立的顏色互稱為「補色」或「互補色」，兩者混合後會產生無彩色。', 'published', 3),
  ('f3e13bae-2d39-0271-cbca-3861723a0b8b', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-04', '觀察色立體之「等色相面」時可發現同一垂直軸的各色其何種屬性是一樣的：', '本單元探討色彩體系與數值符號，核心觀念在於色立體的構造與屬性分布。色立體是以無彩色的明度階段為中心垂直軸，向外延伸代表彩度階段。在等色相面中，垂直軸向代表明度的變化，因此同一條垂直線上各色與中心軸的距離相等，代表其「彩度」屬性完全相同；而同一水平軸向上的各色則是「明度」相同。', 'published', 4),
  ('82d66287-2259-e8da-3cf0-c1831761a962', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-05', '色彩在等色相面上的分布位置，下列何者正確?', '本單元探討色彩體系與數值符號，核心觀念在於等色相面的色彩分布。在色立體的等色相面中，垂直軸為無彩色明度階，水平方向往外則為彩度變化。因此，淺色因明度較高，會分布在靠近上方的外圍邊緣區域；深色則因明度較低而靠近下方。而濁色是靠近中心明度軸（彩度低），純色才是距離明度軸最遠的外緣位置。', 'published', 5),
  ('9154783e-6a00-6b09-5818-c2610174105f', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-06', '色彩的的三屬性依性質有系統的排列，形成三度空間的結構稱為：', '本單元探討色彩表示的色彩體系與數值符號。核心觀念在於「色立體」（Color Solid），它是將色彩的色相、明度、彩度等三屬性，依性質有系統地排列所形成的三度空間結構。色立體的中心軸為無彩色階段（明度階段），外圍圓周代表不同的色相，而由中心軸越向外圍則彩度越高。', 'published', 6),
  ('00f037ca-70e6-b930-ee46-266e26790321', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-07', '色立體（Color Solid）中心軸的名稱，下列何者為非：', '本單元探討色彩體系與數值符號的表示，核心觀念在於色立體的構造與屬性。色立體是將色彩的三屬性依性質有系統地排列所形成的三度空間結構。其中央中心軸為「明度階段」，又稱為「無彩色階段」或「垂直軸」，由下而上明度漸增，最頂端為白色，最底端為黑色；而「彩度階段」則是自中心軸向外圓周方向延伸，越往外緣彩度越高，因此中心軸並不屬於彩度階段。', 'published', 7),
  ('d43975cc-b422-e4b8-e27a-35ed60481046', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-08', '色立體的同一水平軸向，越接近外圓周的色彩具有何種特性?', '本單元探討色彩體系與數值符號的表示，核心觀念在於色立體的結構與屬性分布。色立體是以無彩色階段為中心軸（明度軸），由下而上明度逐漸變高。在同一水平軸向上，各色彩的明度相同，而從中心軸向外圓周方向延伸，色彩的彩度（純度）則會越來越高，因此越接近外圓周的色彩具有彩度越高的特性。', 'published', 8),
  ('f3ed5493-f2a5-38f9-9229-09c05bc91e44', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-09', '關於色立體的敘述，下列何者不正確?', '本單元探討色彩表示法中的色彩體系，核心觀念在於色立體（Color Solid）的結構與三屬性分布。色立體是將色彩的色相、明度、彩度依性質有系統地排列所形成的三度空間結構。在其結構中，中心軸為無彩色階段（明度階段），愈往上方明度愈高，愈往下方明度愈低；由中心軸愈向外圍延伸，色彩的彩度則愈高。由於不同色彩體系（如曼賽爾、PCCS等）所定義的明度與彩度基準不同，因此各色彩體系的色立體型態均不相同。選項A指出「色立體包含了所有的色彩」並不正確，因為色立體僅能納入該體系所能標示與呈現的特定色彩範圍，並非包含世上所有色彩。', 'published', 9),
  ('ae4100e1-f5a6-da05-f9a9-af96d23c764a', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-10', '關於色立體的敘述，下列何者正確?', '本單元探討色彩體系與數值符號的表示，核心觀念在於色立體的建構原理與歷史發展。色立體是將色彩的三屬性（色相、明度、彩度）依系統化排列而成的三度空間結構。垂直中心軸為無彩色的明度階段，愈往上方明度愈高，向下則愈低；從中心軸愈往外圍，色彩的彩度則愈高。在歷史發展中，最先構想出球狀色立體的是19世紀初的德國畫家奧圖倫格（P. Otto Runge），為後續色彩體系的空間概念奠定了重要基礎。', 'published', 10),
  ('3968a391-226e-3be9-9067-beac1aa3b433', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-11', '以色光混色為主的色彩體系是：', '本單元探討色彩表示體系，核心觀念在於混色系與顯色系的區別。CIE表色系（國際照明委員會）是基於加法混色原理，利用物理光譜與色光三原色（RGB）的混色量來定量表示色彩的「混色系」體系，與以目測色票為主的顯色系（如Munsell、PCCS、NCS）不同。', 'published', 11),
  ('ca9e326e-7dff-bb30-8fe1-2c5ee405fcec', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-12', '關於顯色系的敘述，下列何者錯誤?', '本單元探討色彩表示體系，核心觀念在於顯色系與混色系的分類與特性。表色系統主要分為以色光混色為主的「混色系」（如CIE系統）與以色彩顏料（色料）為主的「顯色系」（如曼賽爾、PCCS、NCS系統）。顯色系是透過具體的標準色票，以目測比對的方式來建立與傳達色彩，適用於視覺傳達與設計領域，但由於是以目測為主，在精確度與科學客觀性上較混色系（利用儀器測量色光刺激值）低。', 'published', 12),
  ('ad160ecf-d08e-412b-6849-3e03fc35b866', '036f87e5-edc3-6500-604b-76fef106db70', '3-2-13', '目前國際間誤差最小，最科學化的表色系為：', '本單元探討色彩表示的體系與數值符號。核心觀念在於「CIE表色系」是目前國際間誤差最小、最科學化的表色系統。它由國際照明委員會（CIE）於1931年創立，屬於「混色系」的代表，以數學方式與物理光學數據（三刺激值XYZ）來定量定義色彩，能精確、科學地進行色彩傳達與測量，因此在國際間被廣泛應用。', 'published', 13),
  ('983d1c20-42f7-3617-96be-7c2bc6ff1531', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', '3-3-01', '在電腦影像處理中，色光的混合能產生多少種不同的色彩?', '本單元探討色菜樣本的表示，核心觀念在於電腦數位影像的色光混合原理。電腦螢幕是利用色光三原色（紅 RGB、綠 G、藍 B）進行加法混合來呈現色彩。在數位影像中，RGB 三原色各分為 256 個色階（數值為 0 至 255），因此透過不同比例與強度的色光組合，總共可以產生 256×256×256 = 16,777,216 種（約 1677 萬色）的豐富色彩，這也是現今主流的真彩色（True Color）表示模式。', 'published', 1),
  ('9c4dcf62-aa96-0063-d01d-f94358be7dfa', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', '3-3-02', '數位影像色彩中「R255 G255 B0」呈現何種色彩?', '本單元探討數位影像的色彩表示，核心觀念在於色光的加法混合（RGB色彩模式）。在RGB模式中，紅（R）、綠（G）、藍（B）三原色各分為256個色階（0~255）。當紅色光與綠色光皆達到最高亮度（R255、G255），而藍色光為0（B0）時，兩色光混合後會呈現黃色。', 'published', 2),
  ('0eacfde9-1e5d-f2df-ada8-8850d5741782', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', '3-3-03', '色票的製作會依據不同的色彩體系印製與標示色彩,以日本實用配色體系PCCS為例,下列何者不是以PCCS表色系為製作依據的色票?', '本單元探討色彩表示法與色譜樣本，核心觀念在於理解各類色票的設計依據與分類。經查證，中華色彩研究所色票是依據PCCS表色系製作；日本DIC色票則是依據曼塞爾及PCCS體系進行系統分類。而日本東洋油墨開發的TOYO色票，是參考美國的曼賽爾（Munsell）色彩體系設計，並非以PCCS為主要製作依據。另外補充，FOCOLTONE為法國出版的色票。', 'published', 3),
  ('44bef261-c322-7b37-855c-b72a285a94db', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', '3-3-04', '有關色光RGB混色模式的敘述，下列者不正確?', '本單元探討色彩表示中的色菜樣本表示，核心觀念在於色光RGB混色模式。在RGB色彩模式中，紅（R）、綠（G）、藍（B）三原色各分為256個色階（以0~255數值表示），當R、G、B三個通道數值均為0時呈現黑色，當三者達到最大值255時則呈現白色。因此，選項D中「R255 G0 B255呈現綠色」為錯誤敘述，該數值實際呈現的應為洋紅色，而純綠色應表示為R0 G255 B0。', 'published', 4),
  ('9b187f4f-94a5-0673-3ee0-a6f109144c99', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', '3-3-05', '下列有關電腦用色觀念的敘述，何者錯誤?', '本單元探討色彩表示中色菜樣本的表示，核心觀念在於電腦與印刷的色彩模式與顯色原理。電腦螢幕與數位影像主要採用RGB色光三原色（加法混合）來呈現顏色，透過紅、綠、藍三種色光各256個色階相互混合，可運算出約1677萬種色彩（全彩）。而傳統印刷與電腦列表機的色彩輸出，主要採用CMYK四色油墨（減色法，即青色Cyan、洋紅色Magenta、黃色Yellow、黑色Black）混合而成，而非紅、黃、綠、藍。', 'published', 5),
  ('9bb09882-3fa4-255c-0763-96bef3b1f2da', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', '3-3-06', '影像處理軟體Photoshop的檢色器中，以H：120° ； S：100% ； B：100% 數值表示的色彩，較接近系列何色?', '本單元探討色彩表示法與數位影像用色，核心觀念在於 HSB 色彩模型。在 HSB（或稱為 HSV）模型中，H 代表色相（Hue），以 0° 至 360° 的圓環角度表示，其中紅色的角度為 0°（或 360°）、綠色為 120°、藍色為 240°。本題數值 H 為 120°，且飽和度（S）與明度（B）皆為 100%，代表該色為完全純粹且最明亮的綠色。', 'published', 6),
  ('802c9c07-697f-51a9-99ff-535243326d21', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', '3-3-07', '影像處理軟體Photoshop的檢色器中，以H：330° ； S：100% ； B：100% 數值表示的色彩，若對應RGB系統數值，較接近系列何色?', '本單元探討色彩表示中色菜樣本的表示，核心觀念在於數位影像的色光模式與色彩數值轉換。在Photoshop等影像處理軟體的HSB（HSV）色系中，H（Hue）代表色相，以圓周角度0°至360°表示；S（Saturation）為彩度、B（Brightness）為明度，皆以百分比表示。當H為330°時，在色相環上屬於洋紅色（Magenta-Reds）或稱為洋紅偏紅色系，若彩度與明度皆為100%，對應至RGB色光三原色（範圍各為0~255）的系統數值時，其純色表現最接近的數值即為R255 G0 B255。', 'published', 7),
  ('eb13df9d-0e92-c5db-96c9-eba06ace55e1', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', '3-3-08', '下列色彩表示法何者最接近紅色?', '本單元探討色菜樣本的表示，核心觀念在於數位影像與各色彩體系的表示法。選項A「2R-7.5-1S」接近淺紅色；選項B「S 1080-Y10R」接近鮮黃色；選項D「5R 4/4」在曼塞爾系統中雖然色相為5R（紅），但明度4、彩度4，屬於偏暗濁的紅色。而選項C「H：0° ，S：70% ，B：80%」在HSB色彩體系中，色相H為0°即定義為紅色，且具備較高的飽和度（70%）與明度（80%），因此是四個選項中最接近純正紅色的表示法。', 'published', 8),
  ('2e683d62-cb17-6904-4fb5-3b9853f35de7', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', '3-3-09', '為了表示正確的色彩，下列何種方法「無法」達成共識?', '本單元探討色彩表示與色彩管理，核心觀念在於如何精確且共通地傳達色彩。在色彩的傳達及管理中，為了避免因裝置、螢幕或環境光線產生的色差，必須將色彩轉化為標準共通的表色數值，例如色彩體系數值表示法（如曼賽爾、PCCS）、印刷色量數值法（如CMYK百分比）以及標準演色色票（如PANTONE）。而「自製顏料色卡」缺乏國際標準與通用規範，無法在業界跨平台、跨媒介地達成色彩共識。', 'published', 9),
  ('44723b93-d7bc-bd9b-a598-58e9b91978ed', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', '3-3-10', '色彩的傳達及管理須將色彩依標準規則轉化為共通的表色數值，下列哪一個表色法是不適用、也較不明確的?', '本單元探討色彩表示與樣本。核心觀念在於色彩的傳達與管理必須轉化為共通的表色數值，例如 PANTONE、Munsell 或 CMYK 等系統。由於「Red（紅色）」屬於一般的色彩名稱（即感性色名或基本色名），並不具備精確的標準規則或共通的表色數值，無法達成明確的色彩溝通共識，因此在專業的色彩傳達與管理中是不適用且較不明確的。', 'published', 10),
  ('1c25d7a6-b0f0-79ec-f731-d952fc5c17d8', '776c7d9d-fa82-bd21-24e0-15f0b14aaa31', '3-3-11', '下列何者不是印刷用的油墨色票?', '本單元探討色彩表示法中的色菜樣本表示，核心觀念在於印刷用的油墨色票與色彩體系。常見的印刷油墨色票包含PANTONE（美國彩通）、TOYO（日本東洋油墨）與TRUMATCH等，均為印刷產業中作為色彩溝通與專色調配的標準工具書。而ITTEN（伊登）則是著名色彩學家，其主要貢獻為提出以色彩心理學為基礎的十二色相環與色彩對比理論，並非印刷用的油墨色票系統。', 'published', 11),
  ('f960663b-76e7-2177-df36-3e2ab92709f8', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', '4-1-01', '關於人類視覺對光與色彩訊息的處理過程，下列由左至右的順序，何者正確？', '本單元探討色彩感知與視覺機能，核心觀念在於人類視覺對光與色彩訊息的處理過程。視覺傳導的正確路徑為：光源發出光線，經由眼球的角膜、瞳孔、水晶體及玻璃體調節聚焦，投射至視網膜上的感光細胞（錐狀與桿狀細胞）產生電訊號，最後經由視神經匯整傳遞至大腦視覺皮質，從而產生色彩與形體的主觀視覺感知。', 'published', 1),
  ('e39e3716-e01f-b090-bd10-0c1e39d8ecca', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', '4-1-02', '眼球中，控制光線進出眼球多寡的部位稱為？', '本單元探討色彩感知，核心觀念在於眼球構造與視覺機能。眼球的運作原理與相機相似，其中虹膜環繞在瞳孔外圍，含有肌肉組織，能透過收縮與放鬆來控制瞳孔的大小，進而調節光線進入眼球的多寡，其功能相當於相機的光圈。', 'published', 2),
  ('26897524-86c2-def3-ea20-4261ed4d3aed', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', '4-1-03', '眼球中負責聚集光線、調節焦距的是：', '本單元探討色彩感知與視覺機能，核心觀念在於眼球構造與其生理功能。水晶體（lens）位於虹膜和玻璃體之間，為一透明的雙凸透鏡狀結構，具有彈性與調節能力，是眼球內主要負責聚集光線、調節焦距以使遠近物體清晰呈像的屈光間質。若水晶體隨年齡增長硬化或彈性降低，會導致看近物時的調節能力減弱，即為老花眼。', 'published', 3),
  ('cf4b709a-4a41-af3e-3dd4-b60890a34622', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', '4-1-04', '人類眼球中的視網膜上具有兩種視覺感應細胞是？', '本單元探討色彩與視覺機能，核心觀念在於視網膜上的感光細胞。人類眼球的視網膜上主要具有兩種視覺感應細胞，分別為負責弱光環境下黑白視覺與明暗感應的柱狀細胞（或稱桿狀細胞），以及負責明亮環境下色彩識別與高解析度視覺的錐狀細胞，兩者協同合作以實現視覺感知。', 'published', 4),
  ('dc99010b-5a63-1137-f23c-7407cfe7299a', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', '4-1-05', '眼球中負責分辨色彩的是：', '本單元探討色彩感知，核心觀念在於眼球的視覺機能與感光細胞。人類眼球的視網膜上具有兩種主要感光細胞：桿狀細胞與錐狀細胞。桿狀細胞對光線的明暗反應極為敏感，主要負責暗視覺，但無法分辨顏色；錐狀細胞則集中分布於黃斑部的中心窩，在相對明亮的光線下功能最佳，主要負責明視覺與分辨色彩的色覺。', 'published', 5),
  ('3bbe2540-f225-d799-58f6-1bd28e43b725', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', '4-1-06', '錐狀細胞在眼球那個部位分布最為集中？', '本單元探討色彩的感知與視覺機能，核心觀念在於人類眼球的感光與辨色機制。人類眼球的視網膜上主要有兩種感光細胞：負責感應光線明暗的桿狀細胞，以及負責辨別色彩與高解析度視覺的錐狀細胞。其中，錐狀細胞在視網膜的黃斑區「中心窩」分布最為集中，是形成精細視覺與中心視力的重要部位。', 'published', 6),
  ('41b3841b-749d-cd27-5aa7-4aa015476992', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', '4-1-07', '視網膜中的柱狀細胞是感應光線的：', '本單元探討色彩感知，核心觀念在於眼球的結構與視覺機能。視網膜（Retina）上具有視桿細胞（柱狀細胞）與視錐細胞（錐狀細胞）兩種感光細胞。其中，柱狀細胞對光線的明暗極為敏感，主要負責感應光的亮度、明暗變化以及夜間視覺，但無法辨別顏色；負責分辨色彩與細節的則是錐狀細胞。', 'published', 7),
  ('b4e11f91-260d-b38f-aa09-960f14dbbd45', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', '4-1-08', '有關視網膜上柱狀細胞的構成與作用，下列敘述何者正確？', '本單元探討色彩與視覺機能，核心觀念在於視網膜感光細胞的功能。關於柱狀細胞（桿狀細胞）的正確觀念為：(A) 柱狀細胞數量較錐狀細胞多；(C) 柱狀細胞負責暗視覺，光線愈亮，感應力愈弱；(D) 柱狀細胞負責感應色彩的明度（亮度），無法分辨色相。因此選項(A)、(C)、(D)皆為錯誤敘述。相較之下，柱狀細胞廣泛分布於視網膜上（除中心窩外），故本題依消去法(B)為相對最適當的答案。', 'published', 8),
  ('865070de-13d3-bce0-0cbc-1628b43bf842', 'd5e935ef-35e9-199f-2131-ad2d9957cce4', '4-1-09', '下列關於錐、柱狀細胞的敘述，何者不正確？', '本單元探討色彩與視覺機能。視網膜上的感光細胞分為柱狀細胞與錐狀細胞。柱狀細胞數量較多，對光線明暗非常敏感，且反應速度比錐狀細胞快。因此，選項(C)「柱狀細胞的反應速度比錐狀細胞慢」為錯誤敘述，是本題的正確答案。', 'published', 9),
  ('74c9e0b5-95ae-3a3b-d65e-ffbf31f3ca62', '4caa3fe7-0962-e35d-5c8a-e517e0479171', '4-2-01', '一個顏色受到其他顏色的影響而產生變化之情形稱為？', '本單元探討色彩的對比性，核心觀念在於相鄰或相續的顏色彼此互動，使人對色彩的判斷或感覺產生偏移的錯覺現象。色彩對比依觀看方式可分為同時對比與繼續對比，並包含色相對比、明度對比、彩度對比及面積對比等類型。當不同色彩並列時，常在交界處產生更明顯的邊緣對比，或因視覺生理的補色殘像而影響色彩的鮮豔度與明暗感。', 'published', 1),
  ('75e2975d-44d9-fb0d-ba34-7af8f8c404b6', '7330aaf4-ae55-462e-11f3-bfff61572060', '4-3-01', '色彩會令人感到溫暖或寒冷，是因為：', '本單元探討色彩的感覺與心理，核心觀念在於色彩引起的心理感覺與情感反應。色彩意象與感覺是由色彩引起的心理反應，包含聯想、象徵、好惡以及寒暖、輕重、軟硬、興奮與沉靜等複雜變化。研究指出，暖色調（如紅、橙、黃）通常能帶來活力、溫暖與刺激食慾的感官，而冷色調（如藍、綠）則能營造平靜、冷靜與安定的氛圍，人們對顏色的心理感受也會受到個人經驗、性別與文化背景的影響。', 'published', 1),
  ('acf69d9b-97d7-d121-c659-a67afa120d33', '6ec39331-f103-dd3b-b13c-fbd54a4ca053', '4-4-01', '當我們遠望窗外同距離的海報或廣告時，有些色彩看得很清楚，有些則顯得模糊，這種現象可稱為？', '本單元探討色彩的明視度與注目性，核心觀念在於色彩在視覺傳達與引人注意的心理感受。明視度是指圖形或文字與背景在色彩搭配上的可見度、辨識度，主要受兩者間的明度差影響，明度差越大明視度越高；注目性（誘目性）則是色彩容易引起注意的程度，通常高明度、高彩度及暖色系的前進色具有較高的注目性，常用於海報與標誌設計以達到引人注目的效果。', 'published', 1),
  ('9cd75b46-099d-67bc-7bbc-c76138bf7763', '982acbb9-337d-69a9-043e-81cd82267b5b', '5-1-01', '人們看到蘋果感受到紅色、暖色、美味等共感覺，之後這些感覺傳達到大腦記憶區產生「甜美、蘋果派、高科技等個人好惡與意象」，後段敘述之階段稱為？', '本單元探討色彩嗜好，核心觀念在於個體或群體對色彩的喜好傾向。研究顯示，色彩嗜好並非固定不變，而是受到年齡、性別、文化、民族、地域風土、生活經驗以及流行趨勢等多重生理與心理因素的動態影響，並與色彩所帶來的心理效應和意象聯想密切相關。', 'published', 1),
  ('dbfb5810-b358-1e3e-869c-e409ef245a26', 'b4af36a7-0ad8-93a2-06fd-d228125ad813', '5-2-01', '具有熱情、興奮、危險等意象的色彩是？', '本單元探討色彩呈現中的色彩聯想。核心觀念在於色彩引發的心理感知與具體或抽象事物的心理連結。色彩聯想是基於人類對大自然與生活經驗的累積（如藍色聯想到天空、綠色聯想到草地與和平），進而轉化為共通的心理規範。研究顯示，橙色系、紅色系及無彩色最容易讓受測者產生聯想，且色彩聯想會受到情境、文化、性別等因素影響，是品牌設計與視覺傳達中建立情感共鳴與記憶點的重要基礎。', 'published', 1),
  ('5efbd710-35f0-ab9e-ef5d-8df9e578e37f', 'f290f7f6-c52e-3596-af5d-dbe7a39e3000', '5-3-01', '影響四季彩色感覺最主要的因素是？', '本單元探討色彩認知，核心觀念在於自然環境對色彩感覺的影響。人類對於四季（春、夏、秋、冬）的色彩感覺，最主要源自於對「自然環境」變化的長期觀察與體驗。例如春天萬物復甦的新綠、夏天海洋的藍色、秋天落葉的橙黃色、冬天冰雪的白色等。這些基於自然景觀變化的色彩聯想，是形成四季色彩感覺最直接且主要的因素。', 'published', 1),
  ('25eaee64-a702-5ddf-587a-a66950dc1b2b', '0239f7f4-cac4-6419-4a7e-2afb7664f2ec', '6-1-01', '主張「任何色彩皆由黑與白、明與暗所組成，色彩明度白量與黑量比值，若以2：3或3：4的比例配色就可以產生調和感」的學者是？', '本單元探討配色調和與色彩應用，核心觀念在於掌握色彩的搭配原則與調和理論。常見的配色法包含單色、類似色、互補色及多色相配色等，並可依據賈德、伊登等學者的秩序與對比原理，透過適當調整色相、明度、彩度及面積比例，在變化中求取統一，以達到畫面協調與平衡的視覺效果。', 'published', 1),
  ('0e1a849d-c3af-b9cf-55f1-5c5c9347703b', 'f88cfc0f-8698-8311-3af6-05bce6d46188', '6-2-01', '兩種或是兩種以上的色彩並置一起時，其上下、左右之色彩的重量感相等，稱為：', '本單元探討形式原理與色彩應用，核心觀念在於將美的形式原理（如對稱、均衡、對比、比例、調和、律動、統一等）結合色彩配置。透過相同或相似形色的規律重複、對立色彩的並列，或是色相明度彩度的漸層變化，能創造出具視覺層次與節奏感的畫面，達到整體視覺的和諧與設計訴求。', 'published', 1),
  ('5846a85d-8520-864d-9582-6149dcc129c1', '178f3050-304f-7a46-ca5f-6c01d7a47a5e', '6-3-01', '考慮到消費者的色彩意象及嗜好，並配合市場色彩的機能或流行性，這種選擇色彩的方法稱為？', '本單元探討色彩在設計上的應用，核心觀念在於將色彩學原理落實於視覺傳達與實務設計中。設計師須依據產品定位與目標大眾，整合固有色、環境色與光源的影響，並靈活運用色相、明度、彩度等色彩三要素及色彩心理效應，以建立具識別性的品牌形象，引導使用者視覺焦點，創造兼具美感與實用性的設計作品。', 'published', 1),
  ('207190aa-e7a2-fd19-634d-e033f3f912c2', '534e4d64-402f-3719-316a-6da910b558fa', '9-9-01', '這是一題尚未發布的內容，學生不應看見。', '草稿題僅供 RLS 負向測試。', 'draft', 99);
